//! `logind` client and server shapes (issue #101): the session table and the
//! query `messengerctl sessions` renders. The stubs and the [`Client`] are
//! generated by `midlc` (`Sessions` is bounded to a second in the IDL:
//! `logind` can be sitting at the console prompt, in which case it answers
//! after the next key); the reply helpers are the daemon's (stage C4).

use alloc::vec::Vec;

use libmessenger::{Header, Parcel, VERSION};

use super::client::Native;
use super::{Error, Result};

/// The generated `os.lazy.logind.v1` stubs (`idl/logind.midl`).
pub use messenger_generated::os_lazy_logind_v1 as wire;

/// One session row (the generated `Session` struct).
pub use wire::Session as SessionRecord;

/// The login service's registered name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `logind` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A blocking client of `logind`: `Client::try_connect(Native)`.
pub type Client = wire::Client<Native>;

/// A header for a `logind` parcel of `method`.
fn header(method: u32) -> Header {
    Header {
        version: VERSION,
        flags: 0,
        interface_id: INTERFACE,
        method,
        txn_id: 0,
        reply_to: 0,
        deadline_ns: 0,
    }
}

/// The graphical login screen's system identity (`_greeter`, issue #623):
/// `init` stamps the `greeter` row with it (no capability, no session), and
/// `logind` accepts `Login` from it alone. It owns no file and appears in no
/// account file, like the other service uids (901 `_snd` .. 906 `_devd`).
pub const GREETER_UID: u32 = 907;

/// A reply of `method` carrying `body`.
pub fn reply(method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: header(method),
        body,
        ..Parcel::default()
    }
}

/// A structured refusal of `method`: the positive errno `code` and a short,
/// non-secret reason.
pub fn error_reply(method: u32, code: i64, text: &str) -> Parcel {
    let mut body = libmessenger::Encoder::new();
    // A structured error field cannot overflow a fresh encoder.
    let _ = body.error(messenger_generated::errors::ERROR_FIELD, code as u32, text);
    reply(method, body.finish())
}

/// Encode a `Sessions` reply: the active count, then one record per
/// session, oldest first.
pub fn sessions_reply(sessions: &[SessionRecord], active: u64) -> Result<Parcel> {
    let body = wire::encode_sessions_reply(&wire::SessionsReply {
        active,
        sessions: sessions.to_vec(),
    })
    .map_err(Error::Parcel)?;
    Ok(Parcel {
        header: header(wire::METHOD_SESSIONS),
        body,
        ..Parcel::default()
    })
}
